{"intent":"build","plan":"Create Simon Says memory game using Uno, 4 colored LEDs with resistors, 4 tactile buttons, and a buzzer.","reply":"Simon Says game assembled with Arduino Uno, 4 LEDs, 4 buttons, and a buzzer.","more":false,"clearExisting":true,"board":"full","parts":[{"ref":"U1","type":"uno","props":{"code":"const int btnPins[] = {2, 3, 4, 5};
const int ledPins[] = {8, 9, 10, 11};
const int buzzerPin = 12;
int sequence[100];
int gameLen = 0;
void setup() {
  for(int i=0; i<4; i++) {
    pinMode(btnPins[i], INPUT_PULLUP);
    pinMode(ledPins[i], OUTPUT);
  }
  pinMode(buzzerPin, OUTPUT);
  randomSeed(analogRead(0));
}
void loop() {
  addStep();
  playSeq();
  if(!checkInput()) { gameOver(); gameLen=0; delay(1000); }
  delay(500);
}
void addStep() {
  sequence[gameLen] = random(0, 4);
  gameLen++;
}
void playSeq() {
  for(int i=0; i<gameLen; i++) {
    int p = sequence[i];
    digitalWrite(ledPins[p], HIGH);
    tone(buzzerPin, 200 + p*150, 300);
    delay(400);
    digitalWrite(ledPins[p], LOW);
    delay(200);
  }
}
bool checkInput() {
  for(int i=0; i<gameLen; i++) {
    int pressed = -1;
    unsigned long start = millis();
    while(millis() - start < 2000) {
      for(int j=0; j<4; j++) {
        if(digitalRead(btnPins[j]) == LOW) {
          pressed = j;
          digitalWrite(ledPins[j], HIGH);
          tone(buzzerPin, 200 + j*150, 200);
          delay(250);
          digitalWrite(ledPins[j], LOW);
          while(digitalRead(btnPins[j]) == LOW);
          break;
        }
      }
      if(pressed != -1) break;
    }
    if(pressed != sequence[i]) return false;
  }
  return true;
}
void gameOver() {
  for(int i=0; i<3; i++) {
    tone(buzzerPin, 100, 150);
    delay(200);
  }
}"}},{"ref":"V1","type":"vcc","props":{}},{"ref":"G1","type":"gnd","props":{}},{"ref":"L1","type":"led","props":{"color":"red"}},{"ref":"R1","type":"resistor","props":{"ohms":"220"}},{"ref":"L2","type":"led","props":{"color":"green"}},{"ref":"R2","type":"resistor","props":{"ohms":"220"}},{"ref":"L3","type":"led","props":{"color":"yellow"}},{"ref":"R3","type":"resistor","props":{"ohms":"220"}},{"ref":"L4","type":"led","props":{"color":"blue"}},{"ref":"R4","type":"resistor","props":{"ohms":"220"}},{"ref":"B1","type":"tactile","props":{"bounce":false}},{"ref":"B2","type":"tactile","props":{"bounce":false}},{"ref":"B3","type":"tactile","props":{"bounce":false}},{"ref":"B4","type":"tactile","props":{"bounce":false}},{"ref":"BZ1","type":"buzzer","props":{}}],"connections":[["V1.1","+"],["G1.1","-"],["U1.5V","+"],["U1.GND","-"],["U1.D8","R1.1"],["R1.2","L1.Anode (+)"],["L1.Cathode (−)","-"],["U1.D9","R2.1"],["R2.2","L2.Anode (+)"],["L2.Cathode (−)","-"],["U1.D10","R3.1"],["R3.2","L3.Anode (+)"],["L3.Cathode (−)","-"],["U1.D11","R4.1"],["R4.2","L4.Anode (+)"],["L4.Cathode (−)","-"],["U1.D2","B1.1.l"],["B1.1.r","+"],["U1.D3","B2.1.l"],["B2.1.r","+"],["U1.D4","B3.1.l"],["B3.1.r","+"],["U1.D5","B4.1.l"],["B4.1.r","+"],["B1.2.l","-"],["B2.2.l","-"],["B3.2.l","-"],["B4.2.l","-"],["U1.D12","BZ1.+"],["BZ1.−","-"]]}

