        "code": "#include <Arduino.h>
const int ledPins[] = {2, 3, 4, 5};
const int btnPins[] = {6, 7, 8, 9};
const int buzzerPin = 10;
const int maxLevel = 100;
int gameSequence[maxLevel];
int gameLen = 0;

void setup() {
  for(int i=0; i<4; i++) {
    pinMode(ledPins[i], OUTPUT);
    pinMode(btnPins[i], INPUT_PULLUP);
  }
  pinMode(buzzerPin, OUTPUT);
  randomSeed(analogRead(0));
}

void playTone(int freq, int duration) {
  tone(buzzerPin, freq, duration);
  delay(duration);
  noTone(buzzerPin);
}

void lightLED(int idx, int duration) {
  digitalWrite(ledPins[idx], HIGH);
  if(idx == 0) playTone(200, duration);
  else if(idx == 1) playTone(300, duration);
  else if(idx == 2) playTone(400, duration);
  else playTone(500, duration);
  digitalWrite(ledPins[idx], LOW);
  delay(200);
}

void playSequence() {
  for(int i=0; i<gameLen; i++) {
    lightLED(gameSequence[i], 400);
  }
}

int readButton() {
  while(true) {
    for(int i=0; i<4; i++) {
      if(digitalRead(btnPins[i]) == LOW) {
        digitalWrite(ledPins[i], HIGH);
        if(i == 0) tone(buzzerPin, 200);
        else if(i == 1) tone(buzzerPin, 300);
        else if(i == 2) tone(buzzerPin, 400);
        else tone(buzzerPin, 500);

        while(digitalRead(btnPins[i]) == LOW);
        noTone(buzzerPin);
        digitalWrite(ledPins[i], LOW);
        delay(50);
        return i;
      }
    }
  }
}

void gameOver() {
  for(int i=0; i<3; i++) {
    playTone(100, 200);
    delay(100);
  }
  gameLen = 0;
  delay(1000);
}

void loop() {
  gameSequence[gameLen] = random(0, 4);
  gameLen++;
  if(gameLen > maxLevel) gameLen = maxLevel;

  playSequence();

  for(int i=0; i<gameLen; i++) {
    int pressed = readButton();
    if(pressed != gameSequence[i]) {
      gameOver();
      return;
    }
  }
  delay(1000);
}"
