{"intent":"build","plan":"Simon Says game with Arduino Uno, 4 colored LEDs with resistors, 4 pushbuttons, and a buzzer.","reply":"I have created a Simon Says game circuit using an Arduino Uno, 4 colored pushbuttons and LEDs, and a buzzer!","more":false,"clearExisting":true,"board":"full","parts":[{"ref":"U1","type":"uno","props":{"code":"const int buttonPins[] = {2, 3, 4, 5};
const int ledPins[] = {8, 9, 10, 11};
const int buzzerPin = 12;
int sequence[100];
int sequenceLength = 0;
int playerStep = 0;
bool gameStarted = false;
void setup() {
  for(int i=0; i<4; i++) {
    pinMode(buttonPins[i], INPUT_PULLUP);
    pinMode(ledPins[i], OUTPUT);
  }
  pinMode(buzzerPin, OUTPUT);
  randomSeed(analogRead(0));
}
void loop() {
  if (!gameStarted) {
    delay(1000);
    sequenceLength = 0;
    playerStep = 0;
    gameStarted = true;
  }
  if (playerStep == 0) {
    sequence[sequenceLength] = random(0, 4);
    sequenceLength++;
    playSequence();
  }
  int pressed = getButtonPress();
  if (pressed != -1) {
    digitalWrite(ledPins[pressed], HIGH);
    tone(buzzerPin, 200 + pressed * 100, 200);
    delay(200);
    digitalWrite(ledPins[pressed], LOW);
    if (pressed == sequence[playerStep]) {
      playerStep++;
      if (playerStep >= sequenceLength) {
        playerStep = 0;
        delay(500);
      }
    } else {
      gameOver();
      gameStarted = false;
    }
  }
}
void playSequence() {
  delay(500);
  for(int i=0; i<sequenceLength; i++) {
    int idx = sequence[i];
    digitalWrite(ledPins[idx], HIGH);
    tone(buzzerPin, 200 + idx * 100, 300);
    delay(400);
    digitalWrite(ledPins[idx], LOW);
    delay(200);
  }
}
int getButtonPress() {
  while(true) {
    for(int i=0; i<4; i++) {
      if(digitalRead(buttonPins[i]) == LOW) {
        return i;
      }
    }
  }
}
void gameOver() {
  for(int i=0; i<3; i++) {
    tone(buzzerPin, 100, 200);
